import { DateTime } from "../../src/luxon";

function refAddDays(y, m, d, n) {
  const dt = new Date(0);
  dt.setUTCFullYear(y, m - 1, d);
  dt.setUTCHours(0, 0, 0, 0);
  dt.setUTCDate(dt.getUTCDate() + n);
  return [dt.getUTCFullYear(), dt.getUTCMonth() + 1, dt.getUTCDate()];
}

test("probe days across barrier", () => {
  const problems = [];
  for (let y = 95; y <= 105; y++) {
    for (let m = 1; m <= 12; m++) {
      for (const n of [1, 2, 5, 28, 29, 30, 31, 32, 59, 60, 61, 90, 365, 366, 400]) {
        const start = DateTime.utc(y, m, 15);
        if (!start.isValid) continue;
        const got = start.plus({ days: n });
        const exp = refAddDays(y, m, 15, n);
        if (!got.isValid || got.year !== exp[0] || got.month !== exp[1] || got.day !== exp[2]) {
          problems.push(`${y}-${m}-15 +${n}d => got ${got.isValid ? got.toISODate() : got.invalidReason}, exp ${exp.join("-")}`);
        }
      }
    }
  }
  console.log(problems.slice(0, 40).join("\n"));
  console.log("total problems:", problems.length);
});
EOF
